package countermap

import (
	"sync"
	"testing"
)

func TestIncrementAndGet(t *testing.T) {
	cm := NewCounterMap()
	cm.Increment("a")
	cm.Increment("a")
	cm.Increment("b")
	if cm.Get("a") != 2 {
		t.Fatalf("want 2, got %d", cm.Get("a"))
	}
	if cm.Get("b") != 1 {
		t.Fatalf("want 1, got %d", cm.Get("b"))
	}
	if cm.Get("z") != 0 {
		t.Fatalf("want 0 for missing key")
	}
}

func TestReset(t *testing.T) {
	cm := NewCounterMap()
	cm.Increment("x")
	cm.Reset("x")
	if cm.Get("x") != 0 {
		t.Fatalf("want 0 after reset, got %d", cm.Get("x"))
	}
}

func TestTopN(t *testing.T) {
	cm := NewCounterMap()
	cm.Increment("a")
	cm.Increment("a")
	cm.Increment("a")
	cm.Increment("b")
	cm.Increment("b")
	cm.Increment("c")
	top := cm.TopN(2)
	if top[0] != "a" || top[1] != "b" {
		t.Fatalf("want [a b], got %v", top)
	}
}

func TestConcurrentIncrement(t *testing.T) {
	cm := NewCounterMap()
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			cm.Increment("key")
		}()
	}
	wg.Wait()
	if cm.Get("key") != 1000 {
		t.Fatalf("want 1000, got %d", cm.Get("key"))
	}
}

func TestTopNEmpty(t *testing.T) {
	cm := NewCounterMap()
	if top := cm.TopN(5); len(top) != 0 {
		t.Fatalf("want empty, got %v", top)
	}
}

task_spec.prompt:
Implement CounterMap in countermap.go.

package countermap

import (
    "sort"
    "sync"
)

type CounterMap struct {
    mu      sync.RWMutex
    counts  map[string]int
}

func NewCounterMap() *CounterMap {
    return &CounterMap{counts: make(map[string]int)}
}

func (cm *CounterMap) Increment(key string) {
    cm.mu.Lock()
    defer cm.mu.Unlock()
    cm.counts[key]++
}

func (cm *CounterMap) Get(key string) int {
    cm.mu.RLock()
    defer cm.mu.RUnlock()
    return cm.counts[key]
}

func (cm *CounterMap) Reset(key string) {
    cm.mu.Lock()
    defer cm.mu.Unlock()
    delete(cm.counts, key)
}

func (cm *CounterMap) TopN(n int) []string {
    cm.mu.RLock()
    defer cm.mu.RUnlock()
    type kv struct {
        key   string
        count int
    }
    var pairs []kv
    for k, v := range cm.counts {
        pairs = append(pairs, kv{k, v})
    }
    sort.Slice(pairs, func(i, j int) bool {
        if pairs[i].count != pairs[j].count {
            return pairs[i].count > pairs[j].count
        }
        return pairs[i].key < pairs[j].key
    })
    result := make([]string, 0, n)
    for i := 0; i < n && i < len(pairs); i++ {
        result = append(result, pairs[i].key)
    }
    return result
}

